<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute, onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router'
import {isCaregiver} from '../../api/auth'
import PageHeader from '../../components/common/PageHeader.vue'
import {mealsApi,monday,shiftDay,mealNames,textures,type MyMeals} from '../../api/meals'
const route=useRoute()
const residentId=computed(()=>String(route.params.id || ''))
onBeforeRouteLeave(()=>!busy.value)
onBeforeRouteUpdate(()=>!busy.value)
const week=ref(monday()),data=ref<MyMeals|null>(null),day=ref(0),busy=ref(false),error=ref(''),notice=ref('')
const slots=computed(()=>data.value?.slots.filter(s=>s.day===day.value)||[])
async function load(){if(busy.value)return;busy.value=true;error.value='';notice.value='';data.value=null;try{week.value=monday(week.value);data.value=await mealsApi.resident(residentId.value,week.value)}catch(e){error.value=e instanceof Error?e.message:'读取失败'}finally{busy.value=false}}
onMounted(()=>{const d=new Date();day.value=(d.getDay()+6)%7})
watch(residentId,()=>void load(),{immediate:true})
</script>
<template><div class="page meals meal-personal"><PageHeader :title="data ? `${data.resident_name} · 每日餐食` : '每日餐食'" subtitle="查看每周已发布菜单，查看现有餐食安排，调整需求按岗位流程提交审核。"><RouterLink class="btn" to="/residents">返回老人列表</RouterLink><RouterLink class="btn" :to="`/residents/${residentId}`">查看档案</RouterLink></PageHeader><div class="card meal-toolbar"><label for="my-meal-week">查看周次<input id="my-meal-week" v-model="week" class="input" type="date" :disabled="busy"></label><button class="btn" :disabled="busy||!week" @click="load">查看这一周</button></div><p v-if="error" class="meal-error" role="alert">{{ error }}</p><p v-if="notice" class="meal-notice" role="status">{{ notice }}</p><p v-if="busy" role="status">正在处理，请稍候…</p>
 <template v-if="data"><p v-if="data.caregiver_readonly || data.professional_workflow" class="meal-personal-note">餐食由专业岗位安排，护工仅可查看。如需调整，护工可通过<RouterLink v-if="isCaregiver" :to="{path:'/operations',query:{resident_id:residentId,task:'meal_swap',tab:'tasks'}}">换餐校验</RouterLink><span v-else>护工的换餐校验流程</span>提交申请，由代码校验后交食堂确认。</p><div class="meal-personal-note"><b>正在管理：{{ data.resident_name }}</b><p v-if="!data.reviewed">该老人的饮食资料尚未完成核对，或档案有变化。可先查看菜单，请联系护理部与医务室核实资料。</p><p v-else>“符合登记条件”仅表示通过当前人工登记的规则，不是医疗判断。如有新过敏或不适，请先核对老人档案和饮食需求。</p><p v-if="data.in_care===false">档案当前为已离院状态，不能确认在院餐食。</p></div><p v-if="!data.menu" class="card meal-section">这一周尚未发布菜单，请稍后查看。</p><template v-else><div class="meal-days"><button v-for="n in 7" :key="n" class="btn" :class="{primary:day===n-1}" :aria-pressed="day===n-1" @click="day=n-1">周{{ '一二三四五六日'[n-1] }}<small>{{ shiftDay(data.menu.week_start,n-1).slice(5) }}</small></button></div>
 <section v-for="slot in slots" :key="slot.meal" class="card meal-section"><h2><span class="meal-course-icon"><AppIcon name="leaf" :size="22"/></span>{{ mealNames[slot.meal] }}<small>{{ slot.options.length }} 套餐食可选</small></h2><p>选餐截止：{{ slot.date }} {{ slot.cutoff.slice(0,5) }}（北京时间） <b v-if="slot.closed">· 已截止</b></p><p v-if="slot.selection?.needs_review" class="meal-error">已有选餐需要工作人员重新核对，暂不作为有效备餐依据。</p><div class="meal-summary-grid"><article v-for="option in slot.options" :key="option.id" class="meal-choice" :class="{selected:slot.selection?.option_id===option.id}"><span v-if="slot.selection?.option_id===option.id" class="badge blue">已选择</span><span class="meal-eyebrow">{{ mealNames[slot.meal] }} · {{ textures[option.texture] }}</span><h3>{{ option.name }}</h3><p class="meal-foods">{{ option.foods.join(' · ') }}</p><p>食材：{{ option.ingredients.join('、') }}</p><p>过敏原：{{ option.allergens.join('、') || '本方案未标注；有疑问请询问工作人员' }}</p><p>{{ textures[option.texture] }} · {{ option.tags.join('、') || '无特殊饮食标签' }}</p><p v-if="option.notes">{{ option.notes }}</p><ul v-if="option.reasons.length" class="meal-reasons"><li v-for="why in option.reasons" :key="why">{{ why }}</li></ul><p v-else class="meal-match">符合已登记条件</p><p>剩余 {{ option.remaining }} 份</p><span class="meal-match">{{ slot.selection?.option_id===option.id?'当前已选套餐':'餐食只读，调整请提交换餐申请' }}</span></article></div></section></template></template>
</div></template>
<style src="../../styles/meals.css"></style>
